package reason

// registry is every code, sorted by code. The test holds the order, the class
// prefix and the descriptions.
var registry = []Entry{
	{Code: "call.busy", Class: Call, Description: "the server runs as many calls as it allows; try again later"},
	{Code: "call.choice", Class: Call, Description: "the question names no single device or router; the call lists the choices"},
	{Code: "call.internal", Class: Call, Description: "the server failed while it answered; the answer is not given"},
	{Code: "call.timeout", Class: Call, Description: "the call ran longer than its time limit"},
	{Code: "call.usage", Class: Call, Description: "the inputs are not a valid question"},

	{Code: "default.invalid-action", Class: Default, Description: "a default security rule sets an action PAN-OS does not accept, so the flow is undecided"},
	{Code: "default.none", Class: Default, Description: "no rule and no default rule decides the flow"},
	{Code: "default.precedence-unverified", Class: Default, Description: "local and pushed default rules disagree, and which one wins is not verified"},
	{Code: "default.vsys-missing", Class: Default, Description: "the configuration has no default rules for the vsys"},
	{Code: "default.zones-unknown", Class: Default, Description: "the zones are not known, so the default rule (intrazone or interzone) is not decided"},

	{Code: "dns.canonical-name", Class: DNS, Description: "the name is an alias; the canonical name is as this machine's resolver reports it"},
	{Code: "dns.other-addresses", Class: DNS, Description: "the name resolves to more addresses than the one the answer used"},

	{Code: "doubt.application", Class: Doubt, Description: "a rule names an application, which a flow without traffic cannot match"},
	{Code: "doubt.category-no-url", Class: Doubt, Description: "a rule names a URL category and the question gives no URL"},
	{Code: "doubt.category-undefined", Class: Doubt, Description: "a rule names a URL category the configuration does not define (a PAN-DB category)"},
	{Code: "doubt.dynamic-group", Class: Doubt, Description: "a rule names a dynamic address group whose members come from tags at run time"},
	{Code: "doubt.edl", Class: Doubt, Description: "a rule names an external dynamic list, whose entries the configuration does not hold"},
	{Code: "doubt.fqdn-resolution", Class: Doubt, Description: "a rule names an FQDN address object, and the address the firewall resolves can differ"},
	{Code: "doubt.hip", Class: Doubt, Description: "a rule names a HIP profile, which depends on the endpoint"},
	{Code: "doubt.imei", Class: Doubt, Description: "a rule names an IMEI, which the flow does not carry"},
	{Code: "doubt.imsi", Class: Doubt, Description: "a rule names an IMSI, which the flow does not carry"},
	{Code: "doubt.invalid-action", Class: Doubt, Description: "the deciding rule sets an action PAN-OS does not accept, so the flow is undecided"},
	{Code: "doubt.nat-rule", Class: Doubt, Description: "earlier NAT rules the answer cannot rule out may match the flow instead; each one's reasons name why"},
	{Code: "doubt.not-evaluated.application", Class: Doubt, Description: "the stage did not evaluate the application dimension"},
	{Code: "doubt.not-evaluated.destination-zone", Class: Doubt, Description: "the stage did not evaluate the destination zone"},
	{Code: "doubt.not-evaluated.nat", Class: Doubt, Description: "the stage did not evaluate NAT"},
	{Code: "doubt.not-evaluated.pbf", Class: Doubt, Description: "the stage did not evaluate policy-based forwarding"},
	{Code: "doubt.not-evaluated.service", Class: Doubt, Description: "the stage did not evaluate the service dimension"},
	{Code: "doubt.not-evaluated.source-zone", Class: Doubt, Description: "the stage did not evaluate the source zone"},
	{Code: "doubt.not-evaluated.url", Class: Doubt, Description: "the stage did not evaluate the URL category dimension"},
	{Code: "doubt.not-evaluated.user", Class: Doubt, Description: "the stage did not evaluate the user dimension"},
	{Code: "doubt.not-evaluated.zones", Class: Doubt, Description: "the stage did not evaluate the zones"},
	{Code: "doubt.nw-slice", Class: Doubt, Description: "a rule names a network slice, which the flow does not carry"},
	{Code: "doubt.region", Class: Doubt, Description: "a rule names a region, whose addresses the configuration does not hold"},
	{Code: "doubt.saas-tenant-list", Class: Doubt, Description: "a rule names a SaaS tenant list, which the flow does not carry"},
	{Code: "doubt.saas-user-list", Class: Doubt, Description: "a rule names a SaaS user list, which the flow does not carry"},
	{Code: "doubt.same-action", Class: Doubt, Description: "earlier candidates in doubt share the deciding action, so the verdict holds whichever matches"},
	{Code: "doubt.schedule", Class: Doubt, Description: "a rule has a schedule, which the answer does not evaluate"},
	{Code: "doubt.service-absent", Class: Doubt, Description: "the rule names no service, so the answer cannot judge it on this flow"},
	{Code: "doubt.service-application-default", Class: Doubt, Description: "a rule uses service application-default, whose ports depend on the application"},
	{Code: "doubt.service-kept", Class: Doubt, Description: "rules whose service the answer cannot judge stay candidates"},
	{Code: "doubt.service-no-port", Class: Doubt, Description: "a rule names a service with ports and the question gives no port"},
	{Code: "doubt.service-predefined", Class: Doubt, Description: "a rule names a predefined service, whose ports the configuration does not hold"},
	{Code: "doubt.source-unknown", Class: Doubt, Description: "a NAT rule names a source and the question gives none"},

	{Code: "gap.address-wildcard", Class: Gap, Description: "a wildcard address object matches by mask, and a prefix query cannot decide it"},
	{Code: "gap.application-container", Class: Gap, Description: "an application container groups predefined applications, whose members the configuration does not hold"},
	{Code: "gap.application-filter", Class: Gap, Description: "an application filter selects predefined applications by metadata the configuration does not hold"},
	{Code: "gap.category-match", Class: Gap, Description: "a Category Match URL category lists PAN-DB categories, whose contents the configuration does not hold"},
	{Code: "gap.config-missing", Class: Gap, Description: "the snapshot holds no configuration for the device"},
	{Code: "gap.dynamic-user-group", Class: Gap, Description: "a dynamic user group gets its members from User-ID at run time"},
	{Code: "gap.fetch-failed", Class: Gap, Description: "a fetch of the device failed"},
	{Code: "gap.fib-missing", Class: Gap, Description: "the snapshot has no forwarding table"},
	{Code: "gap.fqdn-no-address", Class: Gap, Description: "an FQDN address object resolves to no address"},
	{Code: "gap.interface-address", Class: Gap, Description: "a NAT rule translates to an interface address the interface state does not hold"},
	{Code: "gap.interfaces-missing", Class: Gap, Description: "the snapshot has no interface state"},
	{Code: "gap.ipv6", Class: Gap, Description: "the answer would need IPv6, which is not simulated"},
	{Code: "gap.load-failed", Class: Gap, Description: "a configuration or a device's data did not load"},
	{Code: "gap.nat-kind", Class: Gap, Description: "a NAT rule translates the source in a way the answer does not read yet"},
	{Code: "gap.nat-port", Class: Gap, Description: "a NAT rule translates to a port that is not a number"},
	{Code: "gap.nat-static", Class: Gap, Description: "a static NAT rule cannot map the address one to one: a side is not one address, range or netmask, the sides differ in shape, or the address lies outside the original"},
	{Code: "gap.no-user-directory", Class: Gap, Description: "no user directory was given, so only local users and groups are searched"},
	{Code: "gap.object-unresolved", Class: Gap, Description: "a name the rules use resolves to no object"},
	{Code: "gap.rib-missing", Class: Gap, Description: "the snapshot has no routing table, so route protocols and alternates are missing"},
	{Code: "gap.snapshot-missing", Class: Gap, Description: "the store has no snapshot for the device at the asked time"},
	{Code: "gap.url-pattern", Class: Gap, Description: "a custom URL category member is not a pattern the answer can read"},
	{Code: "gap.user-directory-stale", Class: Gap, Description: "the user directory is older than its freshness limit"},
	{Code: "gap.version", Class: Gap, Description: "the configuration's PAN-OS version has no schema digest; a near one is used"},
	{Code: "gap.vsys-missing", Class: Gap, Description: "the configuration has no vsys of the asked name"},

	{Code: "input.device", Class: Input, Description: "give the device"},
	{Code: "input.from-zone", Class: Input, Description: "give the source zone"},
	{Code: "input.port", Class: Input, Description: "give the destination port"},
	{Code: "input.protocol", Class: Input, Description: "give the protocol"},
	{Code: "input.router", Class: Input, Description: "give the virtual router"},
	{Code: "input.to-zone", Class: Input, Description: "give the destination zone"},
	{Code: "input.url", Class: Input, Description: "give the URL"},

	{Code: "note.dns-rewrite", Class: Note, Description: "a NAT rule also rewrites DNS answers, which is not simulated"},
	{Code: "note.export-failed", Class: Note, Description: "writing the inventory export for the MCP server failed: the server may still read the previous export, or the new one may not be flushed to disk"},
	{Code: "note.fetch-ha-mode", Class: Note, Description: "the HA mode is not active-passive, so the fetch stays on the device asked"},
	{Code: "note.fetch-ha-state", Class: Note, Description: "the HA state is neither active nor passive, so the fetch stays on the device asked"},
	{Code: "note.fetch-peer-unconfirmed", Class: Note, Description: "the device is passive and its peer does not confirm the pair, so the fetch stays on the device asked"},
	{Code: "note.fetch-peer-unusable", Class: Note, Description: "the device is passive and its peer cannot be used, so the fetch stays on the device asked"},
	{Code: "note.fetch-predefined-missing", Class: Note, Description: "the device did not return its predefined services, so rules that name them stay in doubt"},
	{Code: "note.fresh-document-failed", Class: Note, Description: "a fresh fetch did not get one document"},
	{Code: "note.fresh-failed", Class: Note, Description: "a fresh fetch failed, so the answer comes from the previous snapshot"},
	{Code: "note.ha-binding", Class: Note, Description: "a NAT rule is bound to an HA device; the binding is ignored"},
	{Code: "note.ha-from-peer", Class: Note, Description: "the device was passive; its snapshot comes from the active peer"},
	{Code: "note.ha-peer", Class: Note, Description: "the device is one of an HA pair, and the answer reads one member's snapshot for the pair"},
	{Code: "note.ha-unreadable", Class: Note, Description: "the device's HA state cannot be read, so it is not paired with its peer"},
	{Code: "note.later-deny", Class: Note, Description: "a later hop on the path denies the flow"},
	{Code: "note.local-services", Class: Note, Description: "traffic to the firewall itself meets local services the answer does not model"},
	{Code: "note.loop-snapshot-ages", Class: Note, Description: "a loop crosses snapshots taken at different times and may come from their ages"},
	{Code: "note.nat-applied", Class: Note, Description: "a NAT rule translates the packet on this hop"},
	{Code: "note.nat-no-fallback", Class: Note, Description: "a NAT rule has no fallback, so new sessions are dropped when its pool is exhausted"},
	{Code: "note.nat-pool", Class: Note, Description: "a NAT rule translates the source to one of several addresses; later hops match the first"},
	{Code: "note.rib-unreadable", Class: Note, Description: "the device's routing table cannot be read, so route protocols and alternates are missing"},
	{Code: "note.serial-changed", Class: Note, Description: "the snapshots come from different firewalls, as after an HA failover"},
	{Code: "note.snapshot-skipped", Class: Note, Description: "a damaged snapshot was passed over at the asked time, and an older one answers"},
	{Code: "note.snapshot-stale", Class: Note, Description: "the snapshot is older than the freshness limit"},
	{Code: "note.tls-off", Class: Note, Description: "the device was fetched without TLS certificate verification"},

	{Code: "path.delivered", Class: Path, Description: "the path reaches the destination"},
	{Code: "path.ecmp", Class: Path, Description: "a hop has equal-cost next hops and the path follows one"},
	{Code: "path.hidden-firewall", Class: Path, Description: "the path may cross a firewall that is not in the inventory"},
	{Code: "path.ingress-unknown", Class: Path, Description: "no source was given, so the ingress of the path is not known"},
	{Code: "path.left-by-interface", Class: Path, Description: "the path leaves the estate through an interface"},
	{Code: "path.left-estate", Class: Path, Description: "the path leaves the estate to a next hop that is not in the inventory"},
	{Code: "path.local", Class: Path, Description: "the path ends on a firewall that owns the destination"},
	{Code: "path.loop", Class: Path, Description: "the path returns to a device it already crossed"},
	{Code: "path.nat-distribution", Class: Path, Description: "a NAT rule distributes sessions over several addresses and the path follows one"},
	{Code: "path.nat-no-port", Class: Path, Description: "a NAT rule depends on the port and the question gives none"},
	{Code: "path.nat-no-protocol", Class: Path, Description: "a NAT rule depends on the protocol and the question gives none"},
	{Code: "path.nat-undermatch", Class: Path, Description: "the NAT stage may miss a rule the device would match"},
	{Code: "path.next-hop-type", Class: Path, Description: "a route has a next-hop type the answer does not read yet"},
	{Code: "path.no-route", Class: Path, Description: "a hop has no route to the destination"},
	{Code: "path.pbf", Class: Path, Description: "a policy-based forwarding rule sets the next hop"},
	{Code: "path.start-default-route", Class: Path, Description: "the start of the path was placed by a default route"},
	{Code: "path.too-long", Class: Path, Description: "the path crosses more hops than the limit"},
	{Code: "path.unresolved", Class: Path, Description: "a hop's next hop or interface does not resolve"},
	{Code: "path.virtual-wire", Class: Path, Description: "the ingress forwards without a router (virtual wire or Layer 2), so NAT there is not simulated"},

	{Code: "verdict.default", Class: Verdict, Description: "a default security rule decides the flow"},
	{Code: "verdict.not-relevant", Class: Verdict, Description: "the device's rules do not apply to the flow"},
	{Code: "verdict.relevant-route", Class: Verdict, Description: "a route sends the flow through the device, so its rules apply"},
	{Code: "verdict.rule", Class: Verdict, Description: "a security rule decides the flow"},

	{Code: "zone.derived", Class: Zone, Description: "the zones come from the routes, not from the question"},
	{Code: "zone.dynamic-routing", Class: Zone, Description: "a virtual router learns routes at run time, so the configuration cannot place every address in a zone"},
	{Code: "zone.interface-unzoned", Class: Zone, Description: "an interface that carries the address is in no zone"},
	{Code: "zone.missing", Class: Zone, Description: "no zone is found for an address or a hop"},
	{Code: "zone.no-interface", Class: Zone, Description: "a zone has no interface, so no address can be placed in it"},
	{Code: "zone.none-defined", Class: Zone, Description: "the scope defines no zones"},
	{Code: "zone.other-vsys", Class: Zone, Description: "the zone placements belong to another vsys and are left out"},
	{Code: "zone.placeholder", Class: Zone, Description: "the zone names are placeholders: no external zone joins the vsys in the configuration"},
	{Code: "zone.several-routers", Class: Zone, Description: "more than one logical router covers the address, so every zone is reported"},
	{Code: "zone.undefined", Class: Zone, Description: "a zone the question names is not defined"},
	{Code: "zone.vsys-unknown", Class: Zone, Description: "the vsys that owns an interface is not known"},
}
